-- The owner's pricing rule: purchase price × exchange rate × (1 + margin), rounded to the nearest 500 DZD (1 000 from
-- 100 000 up). Purchase prices and the rule are the owner's business data: admins only, never readable by visitors.
-- Also: Freepik becomes Magnific, Zoom gets its Business plans, and Claude, Gemini, Microsoft 365 and Canva join the
-- store, all priced by the rule from the publishers' official prices (Kaspersky keeps its price until its cost is known).

create table public.pricing_rules (
  id boolean primary key default true check (id), -- a single row
  usd_rate numeric(10, 2) not null default 245 check (usd_rate > 0),
  eur_rate numeric(10, 2) not null default 285 check (eur_rate > 0),
  margin_percent numeric(6, 2) not null default 30 check (margin_percent >= 0),
  updated_at timestamptz not null default now()
);
insert into public.pricing_rules default values;

create table public.variant_costs (
  variant_id uuid primary key references public.product_variants (id) on delete cascade,
  amount numeric(12, 2) not null check (amount >= 0),
  currency text not null check (currency in ('USD', 'EUR', 'DZD')),
  updated_at timestamptz not null default now()
);

alter table public.pricing_rules enable row level security;
alter table public.variant_costs enable row level security;
create policy "pricing rules: admins read" on public.pricing_rules
  for select to authenticated using ((select private.is_admin()));
create policy "pricing rules: admins update" on public.pricing_rules
  for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "costs: admins" on public.variant_costs
  for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
revoke all on public.pricing_rules, public.variant_costs from anon;
revoke insert, delete, truncate on public.pricing_rules from authenticated;

