update public.products set slug = 'magnific', name = 'Magnific', sort = 4, featured = true, hero = false, tagline_ar = 'Freepik أصبح Magnific: ملايين الصور والفيكتور وأدوات الذكاء الاصطناعي، برخصة استعمال تجاري.', tagline_fr = 'Freepik devient Magnific : des millions de photos, vecteurs et outils d’IA, avec licence commerciale.', tagline_en = 'Freepik is now Magnific: millions of photos, vectors and AI tools, with a commercial licence.', description_ar = 'اشتراك Magnific (Freepik سابقاً) رسمي على حسابك أنت، وليس حساباً مشتركاً بين عشرات الأشخاص. اختر Premium أو Premium+ أو Pro، شهرياً أو سنوياً، حسب ما تحتاجه من محتوى وأدوات ذكاء اصطناعي.', description_fr = 'Un abonnement Magnific (anciennement Freepik) officiel sur votre propre compte, pas un compte partagé entre des dizaines de personnes. Choisissez Premium, Premium+ ou Pro, au mois ou à l’année, selon le contenu et les outils d’IA dont vous avez besoin.', description_en = 'An official Magnific (formerly Freepik) subscription on your own account, not an account shared by dozens of people. Choose Premium, Premium+ or Pro, monthly or yearly, depending on the content and AI tools you need.', features_ar = array['المحتوى المميز بدون ذكر المصدر', 'رخصة استعمال تجاري لأعمال زبائنك', 'أدوات الذكاء الاصطناعي حسب الخطة', 'Premium وPremium+ وPro']::text[], features_fr = array['Contenu premium sans attribution', 'Licence commerciale pour les projets de vos clients', 'Outils IA selon la formule', 'Premium, Premium+ et Pro']::text[], features_en = array['Premium content without attribution', 'Commercial licence for client work', 'AI tools depending on the plan', 'Premium, Premium+ and Pro']::text[], requirements_ar = 'البريد الإلكتروني لحسابك في Freepik أو Magnific، أو ننشئ لك حساباً جديداً باسمك.', requirements_fr = 'L’adresse e-mail de votre compte Freepik ou Magnific, ou nous créons un compte à votre nom.', requirements_en = 'The email address of your Freepik or Magnific account, or we create a new account in your name.' where slug = 'freepik-premium';
update public.products set sort = 5, featured = true, hero = false, quote_only = false, description_ar = 'نوفّر اشتراكات Adobe Creative Cloud الرسمية مفعّلة على حسابك: كل التطبيقات (Creative Cloud Pro) أو تطبيق واحد مثل Photoshop أو Illustrator، لمدة سنة.', description_fr = 'Nous fournissons les abonnements Adobe Creative Cloud officiels, activés sur votre compte : toutes les applications (Creative Cloud Pro) ou une seule, comme Photoshop ou Illustrator, pour un an.', description_en = 'We provide official Adobe Creative Cloud subscriptions, activated on your account: every app (Creative Cloud Pro) or a single one such as Photoshop or Illustrator, for one year.' where slug = 'adobe-creative-cloud';
