update public.products set slug = 'zoom-workplace', name = 'Zoom Workplace', sort = 9, featured = false, hero = false, description_ar = 'اشتراك Zoom Workplace رسمي على حسابك، مثالي للدروس عن بعد والاجتماعات مع الزبائن: Pro حتى 100 مشارك، وBusiness حتى 300. السعر للمستخدم الواحد.', description_fr = 'Un abonnement Zoom Workplace officiel sur votre compte, idéal pour les cours en ligne et les réunions avec vos clients : Pro jusqu’à 100 participants, Business jusqu’à 300. Prix par utilisateur.', description_en = 'An official Zoom Workplace subscription on your account, ideal for online classes and client meetings: Pro for up to 100 participants, Business for up to 300. Prices are per user.', features_ar = array['اجتماعات تصل إلى 30 ساعة', 'Pro: حتى 100 مشارك · Business: حتى 300', 'تسجيل سحابي', 'تفعيل خلال 24 ساعة بعد الدفع']::text[], features_fr = array['Réunions jusqu’à 30 heures', 'Pro : jusqu’à 100 participants · Business : jusqu’à 300', 'Enregistrement dans le cloud', 'Activation sous 24 h après paiement']::text[], features_en = array['Meetings up to 30 hours', 'Pro: up to 100 participants · Business: up to 300', 'Cloud recording', 'Activated within 24 hours of payment']::text[] where slug = 'zoom-workplace-pro';
