insert into public.products (id, slug, name, category_id, sort, featured, hero, per_user, quote_only, tagline_ar, tagline_fr, tagline_en, description_ar, description_fr, description_en, features_ar, features_fr, features_en, requirements_ar, requirements_fr, requirements_en) values ('0eff2c35-e0e5-4a5c-bcdb-9e680d22b16e', 'claude-pro', 'Claude Pro', 'ai', 1, true, true, false, false, 'مساعد Anthropic الذكي للكتابة والتحليل والبرمجة، مفعّل على حسابك أنت.', 'L’assistant IA d’Anthropic pour écrire, analyser et coder, activé sur votre propre compte.', 'Anthropic’s AI assistant for writing, analysis and coding, activated on your own account.', 'نفعّل اشتراك Claude Pro الرسمي على حسابك الشخصي في Claude، وتدفع بالدينار نقداً في مكتبنا. لا حسابات مشتركة: حسابك يبقى ملكك، ومحادثاتك تبقى خاصة بك.', 'Nous activons l’abonnement officiel Claude Pro sur votre propre compte Claude, et vous payez en dinars, en espèces à notre bureau. Aucun compte partagé : votre compte reste à vous et vos conversations restent privées.', 'We activate the official Claude Pro subscription on your own Claude account, and you pay in dinars, cash at our office. No shared accounts: your account stays yours and your chats stay private.', array['استعمال أكبر بكثير من النسخة المجانية', 'المشاريع والملفات الطويلة', 'Claude Code للمبرمجين', 'تفعيل خلال 24 ساعة بعد الدفع']::text[], array['Bien plus d’utilisation que la version gratuite', 'Projets et longs documents', 'Claude Code pour les développeurs', 'Activation sous 24 h après paiement']::text[], array['Far more usage than the free plan', 'Projects and long documents', 'Claude Code for developers', 'Activated within 24 hours of payment']::text[], 'البريد الإلكتروني لحسابك في Claude. نشرح لك طريقة التفعيل عندما نتصل بك.', 'L’adresse e-mail de votre compte Claude. Nous vous expliquons l’activation lors de notre appel.', 'The email address of your Claude account. We explain how activation works when we call you.');
