insert into public.products (id, slug, name, category_id, sort, featured, hero, per_user, quote_only, tagline_ar, tagline_fr, tagline_en, description_ar, description_fr, description_en, features_ar, features_fr, features_en, requirements_ar, requirements_fr, requirements_en) values ('4c758b07-6890-47a2-878e-759c21a8f97a', 'gemini-google-ai-pro', 'Gemini · Google AI Pro', 'ai', 3, false, false, false, false, 'Gemini المتقدّم من Google، مع 2 تيرابايت تخزين، مفعّل على حسابك.', 'Le Gemini avancé de Google, avec 2 To de stockage, activé sur votre compte.', 'Google’s advanced Gemini, with 2 TB of storage, activated on your account.', 'نفعّل اشتراك Google AI Pro الرسمي على حساب Google الخاص بك: نماذج Gemini الأقوى داخل التطبيق وفي Gmail ومستندات Google، مع 2 تيرابايت على Google Drive.', 'Nous activons l’abonnement officiel Google AI Pro sur votre propre compte Google : les modèles Gemini les plus puissants dans l’application, dans Gmail et Google Docs, avec 2 To sur Google Drive.', 'We activate the official Google AI Pro subscription on your own Google account: the most capable Gemini models in the app, in Gmail and Google Docs, with 2 TB on Google Drive.', array['نماذج Gemini الأقوى', 'Gemini داخل Gmail وDocs', '2 تيرابايت على Google Drive', 'تفعيل خلال 24 ساعة بعد الدفع']::text[], array['Les modèles Gemini les plus puissants', 'Gemini dans Gmail et Docs', '2 To sur Google Drive', 'Activation sous 24 h après paiement']::text[], array['The most capable Gemini models', 'Gemini in Gmail and Docs', '2 TB on Google Drive', 'Activated within 24 hours of payment']::text[], 'حساب Gmail الذي تريد تفعيل الاشتراك عليه.', 'Le compte Gmail sur lequel activer l’abonnement.', 'The Gmail account to activate the subscription on.');
